type Category = 'Bakery' | 'Floral';
type Unit = 'each' | 'dozen' | 'bunch' | 'box';
type OrderStatus = 'Draft' | 'Confirmed' | 'Ready' | 'Fulfilled' | 'Cancelled';
type MovementReason = 'Received' | 'Sold' | 'Spoiled' | 'Adjustment';

interface Product {
  id: string;
  name: string;
  category: Category;
  unitPricePence: number;
  unit: Unit;
  stockOnHand: number;
  reorderLevel: number;
  allergens?: string[];
  stemCount?: number;
  active: boolean;
}

interface StockMovement {
  id: string;
  productId: string;
  delta: number;
  reason: MovementReason;
  timestamp: string;
  resultingCount: number;
  note?: string;
}

interface Customer {
  id: string;
  name: string;
  phone: string;
  email: string;
}

interface OrderLine {
  productId: string;
  quantity: number;
  unitPricePence: number;
}

interface Order {
  id: string;
  customer: Customer;
  createdAt: string;
  fulfilmentDate: string;
  status: OrderStatus;
  lines: OrderLine[];
  totalPence: number;
}

/**
 * Formats an integer pence amount as a GBP display string.
 * // req-4
 */
function formatGBP(pence: number): string {
  const negative: boolean = pence < 0;
  const abs: number = Math.abs(pence);
  const pounds: number = Math.floor(abs / 100);
  const pencePart: number = abs % 100;
  const penceText: string = pencePart < 10 ? '0' + String(pencePart) : String(pencePart);
  const core: string = String(pounds) + '.' + penceText;
  return negative ? '-£' + core : '£' + core;
}

/**
 * Parses a GBP string (e.g. "12.50") into integer pence. Returns null on invalid input.
 * // req-4
 */
function parseGBP(input: string): number | null {
  if (typeof input !== 'string') {
    return null;
  }
  const trimmed: string = input.trim();
  if (trimmed.length === 0) {
    return null;
  }
  const pattern: RegExp = /^([0-9]+)(\.([0-9]{1,2}))?$/;
  const match: RegExpMatchArray | null = trimmed.match(pattern);
  if (match === null) {
    return null;
  }
  const poundsText: string = match[1];
  const fractionText: string = match[3] === undefined ? '' : match[3];
  const pounds: number = parseInt(poundsText, 10);
  let fraction: number = 0;
  if (fractionText.length === 1) {
    fraction = parseInt(fractionText, 10) * 10;
  } else if (fractionText.length === 2) {
    fraction = parseInt(fractionText, 10);
  }
  return pounds * 100 + fraction;
}

/**
 * Computes the total for a single order line (quantity * captured unit price) in pence.
 * // req-4
 */
function lineTotalPence(quantity: number, unitPricePence: number): number {
  if (!Number.isFinite(quantity) || !Number.isFinite(unitPricePence)) {
    return 0;
  }
  return Math.trunc(quantity) * Math.trunc(unitPricePence);
}

/**
 * Computes the order total in integer pence from its lines.
 * // req-4
 */
function computeOrderTotal(lines: OrderLine[]): number {
  let total: number = 0;
  for (let i: number = 0; i < lines.length; i++) {
    const line: OrderLine = lines[i];
    total += lineTotalPence(line.quantity, line.unitPricePence);
  }
  return total;
}
export { formatGBP, parseGBP, lineTotalPence, computeOrderTotal };

