import { formatGBP, parseGBP, lineTotalPence, computeOrderTotal } from "./chunk.ts";
type Category = 'Bakery' | 'Floral';
type Unit = 'each' | 'dozen' | 'bunch' | 'box';
type OrderStatus = 'Draft' | 'Confirmed' | 'Ready' | 'Fulfilled' | 'Cancelled';

interface Customer {
  id: string;
  name: string;
  phone: string;
  email: string;
}

interface Product {
  id: string;
  name: string;
  category: Category;
  unitPricePence: number;
  unit: Unit;
  stockOnHand: number;
  reorderLevel: number;
  allergens: string[];
  stemCount: number;
  active: boolean;
}

interface OrderLine {
  productId: string;
  quantity: number;
  unitPricePence: number;
  lineTotalPence: number;
}

interface Order {
  id: string;
  customer: Customer;
  createdAt: string;
  fulfilmentDate: string;
  status: OrderStatus;
  lines: OrderLine[];
  totalPence: number;
}

interface ProductStore {
  products: Product[];
}

interface OrderStore {
  orders: Order[];
}

interface MovementStore {
  movements: unknown[];
}

const PRODUCT_STORE: ProductStore = { products: [] };
const ORDER_STORE: OrderStore = { orders: [] };

function hashString(value: string): number {
  let h = 0;
  let i = 0;
  while (i < value.length) {
    h = (h * 31 + value.charCodeAt(i)) % 2147483647;
    i += 1;
  }
  return h;
}

function generateId(prefix: string, seed: string): string {
  const h = hashString(prefix + '|' + seed);
  const base = 'id_' + prefix + '_' + h.toString(36);
  return base;
}

function productExists(id: string): Product | undefined {
  let i = 0;
  while (i < PRODUCT_STORE.products.length) {
    const p = PRODUCT_STORE.products[i];
    if (p.id === id) {
      return p;
    }
    i += 1;
  }
  return undefined;
}

function cloneProduct(p: Product): Product {
  return {
    id: p.id,
    name: p.name,
    category: p.category,
    unitPricePence: p.unitPricePence,
    unit: p.unit,
    stockOnHand: p.stockOnHand,
    reorderLevel: p.reorderLevel,
    allergens: p.allergens.slice(),
    stemCount: p.stemCount,
    active: p.active
  };
}

/**
 * Lists products from the in-memory catalogue, applying optional
 * category, active-status, and free-text query filters.
 *
 * Empty or blank query returns the active-filtered catalogue.
 * A query matching nothing returns an empty list.
 *
 * @param filter - optional category, active flag, and query string
 * @returns filtered array of Product records
 */
// req-2
function listProducts(filter: { category?: Category; active?: boolean; query?: string }): Product[] {
  let result: Product[] = [];
  let i = 0;
  while (i < PRODUCT_STORE.products.length) {
    const p = PRODUCT_STORE.products[i];
    let keep = true;
    if (filter.active !== undefined && p.active !== filter.active) {
      keep = false;
    }
    if (keep && filter.category !== undefined && p.category !== filter.category) {
      keep = false;
    }
    if (keep && filter.query !== undefined && filter.query.trim() !== '') {
      const q = filter.query.trim().toLowerCase();
      if (p.name.toLowerCase().indexOf(q) === -1) {
        keep = false;
      }
    }
    if (keep) {
      result.push(cloneProduct(p));
    }
    i += 1;
  }
  return result;
}

/**
 * Creates a new Product record in the catalogue, validating all input
 * fields. Invalid input is rejected with a field-level error and nothing
 * is persisted. Duplicate names are permitted and every product remains
 * addressable by its own deterministic id.
 *
 * @param input - product fields excluding id and stockOnHand
 * @returns the newly created Product record
 */
// req-3
function createProduct(input: Omit<Product, 'id' | 'stockOnHand'>): Product {
  if (!input || typeof input.name !== 'string' || input.name.trim() === '') {
    throw new Error('field name: a non-empty product name is required');
  }
  if (input.category !== 'Bakery' && input.category !== 'Floral') {
    throw new Error('field category: category must be Bakery or Floral');
  }
  if (
    input.unit !== 'each' &&
    input.unit !== 'dozen' &&
    input.unit !== 'bunch' &&
    input.unit !== 'box'
  ) {
    throw new Error('field unit: unit must be each, dozen, bunch or box');
  }
  if (typeof input.unitPricePence !== 'number' || input.unitPricePence < 0) {
    throw new Error('field unitPricePence: unit price must be a non-negative integer');
  }
  if (typeof input.reorderLevel !== 'number' || input.reorderLevel < 0) {
    throw new Error('field reorderLevel: reorder level must be a non-negative integer');
  }
  const allergens: string[] = Array.isArray(input.allergens) ? input.allergens.slice() : [];
  const stemCount: number = typeof input.stemCount === 'number' ? input.stemCount : 0;
  const id = generateId('product', input.name + '|' + input.category + '|' + String(input.unitPricePence));
  const created: Product = {
    id: id,
    name: input.name,
    category: input.category,
    unitPricePence: input.unitPricePence,
    unit: input.unit,
    stockOnHand: 0,
    reorderLevel: input.reorderLevel,
    allergens: allergens,
    stemCount: stemCount,
    active: input.active === false ? false : true
  };
  PRODUCT_STORE.products.push(created);
  return cloneProduct(created);
}

/**
 * Applies a partial patch to an existing product. Only provided fields are
 * changed. Deactivation is done by patching active to false, never by
 * deletion.
 *
 * @param id - the product id to edit
 * @param patch - partial product fields to update
 * @returns the updated Product record
 */
// req-3
function editProduct(id: string, patch: Partial<Omit<Product, 'id'>>): Product {
  const existing = productExists(id);
  if (existing === undefined) {
    throw new Error('product not found: ' + id);
  }
  if (patch.name !== undefined) {
    if (typeof patch.name !== 'string' || patch.name.trim() === '') {
      throw new Error('field name: a non-empty product name is required');
    }
    existing.name = patch.name;
  }
  if (patch.category !== undefined) {
    if (patch.category !== 'Bakery' && patch.category !== 'Floral') {
      throw new Error('field category: category must be Bakery or Floral');
    }
    existing.category = patch.category;
  }
  if (patch.unit !== undefined) {
    if (
      patch.unit !== 'each' &&
      patch.unit !== 'dozen' &&
      patch.unit !== 'bunch' &&
      patch.unit !== 'box'
    ) {
      throw new Error('field unit: unit must be each, dozen, bunch or box');
    }
    existing.unit = patch.unit;
  }
  if (patch.unitPricePence !== undefined) {
    if (typeof patch.unitPricePence !== 'number' || patch.unitPricePence < 0) {
      throw new Error('field unitPricePence: unit price must be a non-negative integer');
    }
    existing.unitPricePence = patch.unitPricePence;
  }
  if (patch.stockOnHand !== undefined) {
    if (typeof patch.stockOnHand !== 'number' || patch.stockOnHand < 0) {
      throw new Error('field stockOnHand: stock must not be negative');
    }
    existing.stockOnHand = patch.stockOnHand;
  }
  if (patch.reorderLevel !== undefined) {
    if (typeof patch.reorderLevel !== 'number' || patch.reorderLevel < 0) {
      throw new Error('field reorderLevel: reorder level must be a non-negative integer');
    }
    existing.reorderLevel = patch.reorderLevel;
  }
  if (patch.allergens !== undefined) {
    existing.allergens = Array.isArray(patch.allergens) ? patch.allergens.slice() : [];
  }
  if (patch.stemCount !== undefined) {
    existing.stemCount = typeof patch.stemCount === 'number' ? patch.stemCount : 0;
  }
  if (patch.active !== undefined) {
    existing.active = patch.active === true;
  }
  return cloneProduct(existing);
}

/**
 * Soft-deactivates a product by flipping its active flag to false. The
 * record is retained so historical order lines continue to resolve.
 *
 * @param id - the product id to deactivate
 * @returns the deactivated Product record
 */
// req-3
function deactivateProduct(id: string): Product {
  const existing = productExists(id);
  if (existing === undefined) {
    throw new Error('product not found: ' + id);
  }
  existing.active = false;
  return cloneProduct(existing);
}
export { listProducts, createProduct, editProduct, deactivateProduct };

